   "id": "bio-mock2-qa",
   "title": "模拟卷（二）· 实验综合",
   "icon": "🧾",
   "kind": "qa",
   "scope": "final",
   "desc": "4 道实验综合题：临时装片、鼠妇探究、种子结构、口腔消化。",
   "source": "自主整理 · 覆盖人教版 2024 版七年级上册全册",
   "items": [
    {
     "q": "某同学制作洋葱鳞片叶内表皮临时装片并用显微镜观察。\n（1）请写出制作临时装片的正确操作顺序（用序号）：① 盖盖玻片 ② 滴清水 ③ 撕取表皮 ④ 展平 ⑤ 染色 ⑥ 擦拭载玻片。\n（2）盖盖玻片时为什么要让一边先接触水滴再缓缓放下？\n（3）若视野中出现边缘黑、中央亮的圆形物像，是什么？如何避免？",
     "a": "（1）⑥ 擦拭 → ② 滴清水 → ③ 撕取表皮 → ④ 展平 → ① 盖盖玻片 → ⑤ 染色。\n（2）避免盖玻片下产生气泡，影响观察。\n（3）是气泡。原因是盖盖玻片方法不当；避免方法是让盖玻片一边先接触水滴，再缓缓放下，并用镊子轻压赶出气泡。"
    },
    {
     "q": "某小组探究「光对鼠妇分布的影响」：在铁盘内均匀铺湿土，以中线为界，一侧遮光、一侧见光，中央放入 10 只鼠妇，每分钟统计一次两侧鼠妇数，共统计 10 次。\n（1）该实验提出的问题是？作出的假设是？\n（2）实验的变量是什么？为什么要设置明暗两种环境？\n（3）为什么要用 10 只鼠妇并统计 10 次取平均值？实验结束后应如何处理鼠妇？",
     "a": "（1）问题：光会影响鼠妇的分布吗？假设：鼠妇适于生活在阴暗的环境中，光会影响鼠妇的分布。\n（2）变量是光照（有光/无光）。设置明暗两种环境形成对照实验，除光照外其他条件（湿度、温度等）相同且适宜。\n（3）用 10 只并多次统计取平均值，可减小偶然性、避免实验误差，使结果更可靠。实验结束后应把鼠妇放回适合它生存的自然环境。"
    },
    {
     "q": "下图为菜豆种子和玉米种子的基本结构示意图（文字描述：菜豆种子有种皮和两片子叶，营养储存在子叶中；玉米种子有果皮和种皮、一片子叶、胚乳，营养储存在胚乳中）。\n（1）两者都有的结构是什么？\n（2）菜豆种子和玉米种子储存营养的结构分别是什么？\n（3）玉米种子中遇碘变蓝的结构是什么？说明其中含有什么物质？",
     "a": "（1）都有种皮和胚；胚都由胚芽、胚轴、胚根、子叶组成，胚是新植物的幼体。\n（2）菜豆种子的营养储存在子叶中（两片）；玉米种子的营养主要储存在胚乳中（一片子叶转运营养）。\n（3）胚乳。遇碘变蓝说明含有丰富淀粉（营养物质）。"
    },
    {
     "q": "某同学在探究「馒头在口腔中的变化」时，取等量馒头碎屑分别放入 A、B 两试管：A 加 2mL 唾液并充分搅拌，B 加 2mL 清水并充分搅拌，两管同时放入 37℃ 温水中 10 分钟，取出后各滴 2 滴碘液。\n（1）该实验的变量是什么？B 管起什么作用？\n（2）预测实验现象并解释原因。\n（3）为什么要把试管放在 37℃ 温水中？",
     "a": "（1）变量是唾液（有无唾液淀粉酶）；B 管是对照组，起对照作用。\n（2）A 管不变蓝（或颜色很浅），因为唾液淀粉酶将淀粉分解为麦芽糖；B 管变蓝，因为清水不能分解淀粉，淀粉遇碘变蓝。\n（3）37℃ 接近人体口腔温度，是唾液淀粉酶发挥作用的适宜温度，保证酶活性最强。"
    }
   ]
